using System;using System.Linq;using System.IO;using System.Text;using System.Collections.Generic;using System.Web.Script.Serialization;
public class ArchiveMetric {public double LowSeconds,MidSeconds,HighSeconds;public double Sum,Weight,Peak,Min=Double.MaxValue;public void Add(double value,double seconds){if(value<40)LowSeconds+=seconds;else if(value<80)MidSeconds+=seconds;else HighSeconds+=seconds;Sum+=value*seconds;Weight+=seconds;Peak=Math.Max(Peak,value);Min=Math.Min(Min,value);}public double Mean{get{return Weight>0?Sum/Weight:0;}}}
public class ArchiveHour {public DateTime Utc;public Dictionary<string,ArchiveMetric> Metrics=new Dictionary<string,ArchiveMetric>();public double Download,Upload,DirectDownload,DirectUpload,ProxyDownload,ProxyUpload,Unclassified;public bool NetworkRecorded,SplitRecorded;}
public class ArchiveMonth {public List<ArchiveHour> Hours=new List<ArchiveHour>();}
public sealed class MonitorArchive {
 readonly string folder;readonly object gate=new object();readonly Dictionary<string,ArchiveMonth> months=new Dictionary<string,ArchiveMonth>();readonly HashSet<string> blocked=new HashSet<string>(),dirty=new HashSet<string>();DateTime previous,flushed;string network;public string Status="等待历史采样";public int Revision;
 public MonitorArchive(string data){folder=Path.Combine(data,"monitor-history");}
 static string Month(DateTime t){return t.ToUniversalTime().ToString("yyyy-MM");}
 ArchiveMonth Load(string key){ArchiveMonth m;if(months.TryGetValue(key,out m))return m;m=new ArchiveMonth();string p=Path.Combine(folder,key+".json");try{if(File.Exists(p)){if(new FileInfo(p).Length>8388608)throw new IOException("历史文件过大");m=new JavaScriptSerializer{MaxJsonLength=8388608}.Deserialize<ArchiveMonth>(File.ReadAllText(p));if(m==null||m.Hours==null||m.Hours.Any(h=>h==null||h.Metrics==null))throw new ArgumentException("历史结构无效");}}catch(Exception e){if(!(e is IOException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is UnauthorizedAccessException))throw;blocked.Add(key);Status="历史文件读取失败，已保留原文件："+key;m=new ArchiveMonth();}months[key]=m;return m;}
 ArchiveHour Hour(DateTime utc){utc=utc.ToUniversalTime();string key=Month(utc);var m=Load(key);var hour=new DateTime(utc.Year,utc.Month,utc.Day,utc.Hour,0,0,DateTimeKind.Utc);var b=m.Hours.FirstOrDefault(h=>h.Utc==hour);if(b==null){b=new ArchiveHour{Utc=hour};m.Hours.Add(b);}dirty.Add(key);return b;}
 public void Observe(SystemSample s){if(s==null||s.Utc==default(DateTime))return;lock(gate){double seconds=(s.Utc-previous).TotalSeconds;if(previous==default(DateTime)){previous=s.Utc;network=s.NetworkId;return;}if(seconds<=0)return;previous=s.Utc;if(seconds>10){network=s.NetworkId;return;}var b=Hour(s.Utc);foreach(string key in new[]{"cpu","gpu","memory","cpuTemp","gpuTemp","disk","download","upload","diskRead","diskWrite","frequency","codex5h","codex7d","diskTemp","vram","memoryUsed","memoryAvailable","vramUsed","vramTotal"}){double? v=key=="memoryUsed"?(double?)s.MemoryUsed:key=="memoryAvailable"?(double?)(s.MemoryTotal-s.MemoryUsed):key=="vramUsed"?s.VramUsed/1024:key=="vramTotal"?s.VramTotal/1024:key=="diskTemp"?s.DiskTemperature:key=="vram"?(s.VramTotal>0?s.VramUsed/s.VramTotal*100:null):MonitorEngine.Value(s,key);if((key=="gpu"||key=="gpuTemp"||key=="vram")&&s.GpuSampleUtc!=default(DateTime)&&(s.Utc-s.GpuSampleUtc).TotalSeconds>5)continue;if(!v.HasValue||Double.IsNaN(v.Value)||Double.IsInfinity(v.Value)||v<0)continue;ArchiveMetric metric;if(!b.Metrics.TryGetValue(key,out metric))b.Metrics[key]=metric=new ArchiveMetric();metric.Add(v.Value,seconds);}if(network==s.NetworkId&&s.Download.HasValue&&s.Upload.HasValue){b.Download+=Math.Max(0,s.Download.Value)*seconds;b.Upload+=Math.Max(0,s.Upload.Value)*seconds;b.NetworkRecorded=true;}network=s.NetworkId;Revision++;if(blocked.Count==0)Status="按小时归档 · 原始采样时长加权，空白表示无数据";if((s.Utc-flushed).TotalSeconds>=60)Flush();}}
 public void AddSplit(DateTime utc,double directDown,double directUp,double proxyDown,double proxyUp,double unknown){lock(gate){var b=Hour(utc);b.DirectDownload+=Math.Max(0,directDown);b.DirectUpload+=Math.Max(0,directUp);b.ProxyDownload+=Math.Max(0,proxyDown);b.ProxyUpload+=Math.Max(0,proxyUp);b.Unclassified+=Math.Max(0,unknown);b.SplitRecorded=true;Revision++;}}
 public ArchiveHour[] Range(DateTime start,DateTime end){lock(gate){var utcStart=start.ToUniversalTime();var utcEnd=end.ToUniversalTime();for(DateTime month=new DateTime(utcStart.Year,utcStart.Month,1,0,0,0,DateTimeKind.Utc);month<utcEnd;month=month.AddMonths(1))Load(Month(month));return months.Values.SelectMany(m=>m.Hours).Where(h=>h.Utc>=start.ToUniversalTime()&&h.Utc<end.ToUniversalTime()).OrderBy(h=>h.Utc).Select(h=>new ArchiveHour{Utc=h.Utc,Download=h.Download,Upload=h.Upload,DirectDownload=h.DirectDownload,DirectUpload=h.DirectUpload,ProxyDownload=h.ProxyDownload,ProxyUpload=h.ProxyUpload,Unclassified=h.Unclassified,NetworkRecorded=h.NetworkRecorded,SplitRecorded=h.SplitRecorded,Metrics=h.Metrics.ToDictionary(p=>p.Key,p=>new ArchiveMetric{Sum=p.Value.Sum,Weight=p.Value.Weight,Peak=p.Value.Peak,Min=p.Value.Min,LowSeconds=p.Value.LowSeconds,MidSeconds=p.Value.MidSeconds,HighSeconds=p.Value.HighSeconds})}).ToArray();}}
 public void Flush(){lock(gate){try{Directory.CreateDirectory(folder);}catch(IOException){Status="历史目录无法写入，保留内存记录";return;}catch(UnauthorizedAccessException){Status="历史目录无法写入，保留内存记录";return;}foreach(string key in dirty.ToArray()){if(blocked.Contains(key))continue;string path=Path.Combine(folder,key+".json"),temp=path+".tmp";try{File.WriteAllText(temp,new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(months[key]),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);dirty.Remove(key);}catch(IOException){Status="历史保存失败，内存记录保留";}catch(UnauthorizedAccessException){Status="历史目录无法写入，内存记录保留";}}flushed=DateTime.UtcNow;}}
}
